script:
class Component extends DCLogic {
  constructor(props) {
    super(props);
    const INIT = { site: { name: "Илья Перагов", slug: "peragov", own: true, color: "#0E6A40", logo: "", photo: "", sign: "Агент Housebook, Дубай", langs: ["Русский", "English"], scope: "all", projects: [], cur: "USD", demo: true }, on: true };
    this.state = Object.assign({ site: null, on: true, fresh: false, wiz: 0, edit: false, draft: null, vis: 30, ppv: 'phone', wpv: 'phone', tried: false, m: '', toast: '' }, INIT);
  }

  kit() {
    if (this._k) return this._k;
    const NB = ' ';
    const RATE = { USD: 1, EUR: 0.93, AED: 3.67, RUB: 92, THB: 34.5 };
    const CAT = [
      { id: 'creek', n: 'Creek Residence', c: 'Дубай', co: 'ОАЭ', p: 1450000, cur: 'AED' },
      { id: 'marina', n: 'Marina Shore', c: 'Дубай', co: 'ОАЭ', p: 1180000, cur: 'AED' },
      { id: 'mira', n: 'Mira Coral Bay', c: 'Рас-эль-Хайма', co: 'ОАЭ', p: 555000, cur: 'AED' },
      { id: 'limassol', n: 'Limassol Gardens', c: 'Лимассол', co: 'Кипр', p: 310000, cur: 'EUR' },
      { id: 'batumi', n: 'Batumi Sea Tower', c: 'Батуми', co: 'Грузия', p: 115000, cur: 'USD' },
      { id: 'antalya', n: 'Antalya Hills', c: 'Анталья', co: 'Турция', p: 165000, cur: 'USD' },
      { id: 'tersane', n: 'Tersane Istanbul', c: 'Стамбул', co: 'Турция', p: 1125000, cur: 'USD' },
      { id: 'rawai', n: 'Proud Rawai Resort', c: 'Пхукет', co: 'Таиланд', p: 3526000, cur: 'THB' },
      { id: 'beverly', n: 'Beverly mountain Bay', c: 'Паттайя', co: 'Таиланд', p: 3195000, cur: 'THB' },
      { id: 'serene', n: 'Serene Raya Villas Bangjo', c: 'Пхукет', co: 'Таиланд', p: 22500000, cur: 'THB' },
      { id: 'zenith', n: 'Zenith Pattaya II', c: 'Паттайя', co: 'Таиланд', p: 3840000, cur: 'THB' },
      { id: 'skypark', n: 'Skypark Celeste', c: 'Пхукет', co: 'Таиланд', p: 5400000, cur: 'THB' }
    ];
    CAT.forEach((o) => { o.usd = o.p / RATE[o.cur]; });
    const COLORS = [['#00732D', 'Зелёный'], ['#0E6A40', 'Нефрит'], ['#005820', 'Тёмный зелёный'], ['#267953', 'Хвоя'], ['#B3122E', 'Красный'], ['#121517', 'Чернила'], ['#4D5254', 'Графит'], ['#0B5533', 'Тёмный нефрит']];
    const fm = (n) => String(Math.round(n / 1000) * 1000).replace(/\B(?=(\d{3})+(?!\d))/g, NB);
    const TAKEN = ['ilya', 'ivan', 'anna', 'dubai', 'housebook', 'admin', 'info', 'sale', 'peragov2'];
    const TR = { а: 'a', б: 'b', в: 'v', г: 'g', д: 'd', е: 'e', ё: 'e', ж: 'zh', з: 'z', и: 'i', й: 'y', к: 'k', л: 'l', м: 'm', н: 'n', о: 'o', п: 'p', р: 'r', с: 's', т: 't', у: 'u', ф: 'f', х: 'h', ц: 'ts', ч: 'ch', ш: 'sh', щ: 'sch', ъ: '', ы: 'y', ь: '', э: 'e', ю: 'yu', я: 'ya' };
    const slugOf = (s) => String(s || '').toLowerCase().split('').map((ch) => (TR[ch] !== undefined ? TR[ch] : ch)).join('').replace(/[^a-z0-9]+/g, '-').replace(/^-+|-+$/g, '').slice(0, 30);
    const mono = (s) => { const w = String(s || '').trim().split(/\s+/).filter(Boolean); return (w.length ? w.slice(0, 2).map((x) => x[0]).join('') : 'HB').toUpperCase(); };
    const DEMO_DAYS = [4, 6, 3, 9, 5, 8, 3];
    const DEMO_START = [1, 3, 1, 4, 2, 4, 2];
    const EARLY_START = [1, 1, 2, 1, 2, 1, 2, 1, 2, 2, 1, 2, 2, 1, 1, 2, 2, 1, 3, 1, 2, 2, 0];
    const LEAD_IDX = [4, 19, 26];
    const EARLY = [2, 3, 4, 3, 5, 2, 4, 3, 6, 4, 3, 5, 4, 2, 3, 5, 4, 3, 6, 4, 4, 4, 5];
    this._k = { NB, RATE, CAT, COLORS, fm, TAKEN, slugOf, mono, DEMO_DAYS, EARLY, DEMO_START, EARLY_START, LEAD_IDX };
    return this._k;
  }

  _y(e) { try { const m = document.querySelector('main.kab__main'); return Math.round(e.currentTarget.getBoundingClientRect().top - m.getBoundingClientRect().top); } catch (x) { return 120; } }
  say(msg, e) { const y = this._y(e); this.setState({ toast: msg, toastY: Math.max(8, y + ((e && e.currentTarget && e.currentTarget.offsetHeight) || 40) + 8) }); clearTimeout(this._tt); this._tt = setTimeout(() => this.setState({ toast: '' }), 3800); }
  openM(name, e) { const y = this._y(e); this.setState({ m: name, mTop: Math.max(16, y - 40) }); }
  closeM() { this.setState({ m: '' }); }

  blank() { return { name: '', slug: '', own: false, color: '#0E6A40', logo: '', photo: '', sign: '', langs: ['Русский'], scope: 'all', projects: [], cur: 'USD' }; }
  openWiz(step, edit) {
    const S = this.state;
    const d = edit && S.site ? JSON.parse(JSON.stringify(S.site)) : (S.draft || this.blank());
    this.setState({ wiz: step, edit: !!edit, draft: d, tried: false });
  }
  setD(p) { this.setState({ draft: Object.assign({}, this.state.draft, p) }); }
  slugState(d) {
    const k = this.kit();
    if (!d.slug) return 'empty';
    if (!/^[a-z0-9-]{3,30}$/.test(d.slug) || /^-|-$/.test(d.slug)) return 'bad';
    if (k.TAKEN.indexOf(d.slug) >= 0) return 'taken';
    return 'ok';
  }
  stepOk(step) {
    const d = this.state.draft;
    if (step === 1) return !!d.name.trim() && (this.state.edit || this.slugState(d) === 'ok');
    if (step === 5) return d.scope === 'all' || d.projects.length > 0;
    return true;
  }
  file(e, key, errKey) {
    const f = e.target.files && e.target.files[0];
    if (!f) return;
    if (f.size > 5 * 1024 * 1024) { this.setState({ [errKey]: 'Файл больше 5 МБ. Выберите файл поменьше.' }); return; }
    const r = new FileReader();
    r.onload = () => { this.setState({ [errKey]: '' }); this.setD({ [key]: String(r.result) }); };
    r.readAsDataURL(f);
  }
  wNext(e) {
    if (e && e.preventDefault) e.preventDefault();
    const S = this.state;
    if (!this.stepOk(S.wiz)) { this.setState({ tried: true }); return; }
    if (S.edit) { this.setState({ site: JSON.parse(JSON.stringify(S.draft)), wiz: 0, edit: false, toast: 'Изменения сохранены', toastY: 120 }); clearTimeout(this._tt); this._tt = setTimeout(() => this.setState({ toast: '' }), 3800); return; }
    if (S.wiz < 6) { this.setState({ wiz: S.wiz + 1, tried: false }); return; }
    this.setState({ site: Object.assign(JSON.parse(JSON.stringify(S.draft)), { demo: false }), on: true, fresh: true, wiz: 0, draft: null, toast: 'Сайт опубликован', toastY: 120 });
    clearTimeout(this._tt); this._tt = setTimeout(() => this.setState({ toast: '' }), 3800);
  }

  pvVals(px, d, mode) {
    const k = this.kit();
    const list = d.scope === 'all' || !d.projects.length ? k.CAT : k.CAT.filter((o) => d.projects.indexOf(o.id) >= 0);
    const IM = ['', 'i1', 'i2', 'i3'];
    const cards = list.slice(0, 4).map((o, i) => ({ n: o.n, c: o.c, co: o.co, i: IM[i % 4], p: k.fm(o.usd * k.RATE[d.cur]) + k.NB + d.cur }));
    const v = {};
    v[px + 'Cls'] = mode === 'desk' ? 'sy-pv--desk' : 'sy-pv--phone';
    v[px + 'Color'] = d.color;
    v[px + 'Url'] = (d.slug || 'vash-adres') + '.housebook.site';
    v[px + 'HasLogo'] = !!d.logo; v[px + 'NoLogo'] = !d.logo; v[px + 'Logo'] = d.logo;
    v[px + 'HasPhoto'] = !!d.photo; v[px + 'NoPhoto'] = !d.photo; v[px + 'Photo'] = d.photo;
    v[px + 'Mono'] = k.mono(d.name);
    v[px + 'Name'] = d.name || 'Ваше имя';
    v[px + 'Cards'] = cards;
    v[px + 'Sub'] = (d.sign ? d.sign + '. ' : '') + (d.langs.length ? d.langs.join(', ') : 'Русский');
    return v;
  }

  renderVals() {
    const S = this.state, k = this.kit(), set = (o) => this.setState(o);
    const site = S.site, d = S.draft || this.blank();
    const demo = !!(site && site.demo);
    const toastStyle = 'top:' + (S.toastY || 80) + 'px;width:max-content;max-width:min(420px,calc(100% - 32px))';
    const V = {
      toastOn: !!S.toast, toast: S.toast || '', toastStyle, mOn: !!S.m, ovlStyle: 'padding-top:' + (S.mTop || 24) + 'px',
      closeOvl: (e) => { if (e.target === e.currentTarget) this.closeM(); }, closeBtn: () => this.closeM(),
      helpOpen: (e) => this.openM('help', e), m_help: S.m === 'help', m_share: S.m === 'share',
      openShare: (e) => this.openM('share', e),
      copy: (e) => { try { navigator.clipboard.writeText('https://' + (site ? site.slug : '') + '.housebook.site'); } catch (x) { /* буфер недоступен в превью */ } this.say('Адрес скопирован', e); },
      sayWa: (e) => this.say('В кабинете откроется WhatsApp с адресом сайта', e), sayTg: (e) => this.say('В кабинете откроется Telegram с адресом сайта', e), sayMail: (e) => this.say('В кабинете откроется письмо с адресом сайта', e),
      dlQr: (e) => this.say('QR-код сохранён', e), openSite: (e) => this.say('В кабинете сайт откроется в новой вкладке', e),
      noSite: !site, hasSite: !!site, buildSite: () => this.openWiz(1, false),
      slug: site ? site.slug : ''
    };
    /* страница работающего сайта */
    if (site) {
      const on = S.on;
      const N = 30, z = new Array(N).fill(0);
      const vAll = demo ? k.EARLY.concat(k.DEMO_DAYS) : z, sAll = demo ? k.EARLY_START.concat(k.DEMO_START) : z;
      const lAll = z.map((_, i) => (demo && k.LEAD_IDX.indexOf(i) >= 0 ? 1 : 0));
      const from = S.vis === 7 ? N - 7 : 0;
      const days = vAll.slice(from), st = sAll.slice(from), ld = lAll.slice(from);
      const sum = (a) => a.reduce((x, y) => x + y, 0);
      const max = Math.max.apply(null, days.concat([1]));
      const WD = ['воскресенье', 'понедельник', 'вторник', 'среда', 'четверг', 'пятница', 'суббота'], WS = ['вс', 'пн', 'вт', 'ср', 'чт', 'пт', 'сб'];
      const MN = ['января', 'февраля', 'марта', 'апреля', 'мая', 'июня', 'июля', 'августа', 'сентября', 'октября', 'ноября', 'декабря'];
      const dt = (i) => new Date(2026, 9, 10 + from + i);
      const dd = (i) => { const t = dt(i); return ('0' + t.getDate()).slice(-2) + '.' + ('0' + (t.getMonth() + 1)).slice(-2); };
      const dayRows = days.map((v, i) => {
        const t = dt(i), today = i === days.length - 1, full = t.getDate() + ' ' + MN[t.getMonth()] + ', ' + WD[t.getDay()];
        return { v, s: st[i], l: ld[i], h: Math.round(v / max * 100), cls: 'sy-d' + (ld[i] ? ' is-lead' : ''), lCls: ld[i] ? '' : 'is-hide', full: full + (today ? ' (сегодня)' : ''),
          label: full + ': посетителей ' + v + ', начали подбор ' + st[i] + (ld[i] ? ', заявок ' + ld[i] : ''),
          lb: today ? 'сегодня' : S.vis === 7 ? WS[t.getDay()] : dd(i), lbCls: S.vis === 7 || (i % 7 === 0 && i < 24) || today ? 'is-lb' : '' };
      });
      const total = sum(days);
      const fn = [sum(days), sum(st), demo ? (S.vis === 7 ? 2 : 4) : 0, sum(ld)];
      const FT = ['Зашли на сайт', 'Начали подбор', 'Оставили контакт', 'Заявки'];
      const leads = demo ? [{ id: 'c7', name: 'Нина Фёдорова', when: '5 ноября, 11:20', src: 'Чарли в Telegram' }, { id: 'c2', name: 'Анна Гордеева', when: '29 октября, 18:05', src: 'Форма на сайте' }, { id: 'c5', name: 'Игорь Беляев', when: '14 октября, 09:40', src: 'Чарли в Telegram' }] : [];
      const sc = site.scope === 'all' ? 'Весь каталог' : 'Выбрано проектов: ' + site.projects.length;
      const colorName = (k.COLORS.filter((c) => c[0] === site.color)[0] || ['', ''])[1];
      const card = (cls, t, v, n, step, extra) => Object.assign({ cls, t, v, n, go: () => this.openWiz(step, true), dot: false, color: site.color }, extra || {});
      Object.assign(V, {
        stCls: on ? 'badge--ok' : 'badge--muted', stText: on ? 'Работает' : 'Выключен', siteOn: on, isOff: !on, fresh: S.fresh,
        toggleOn: () => set({ on: !on, fresh: false }),
        leads30: demo ? 3 : 0, leadsAll: demo ? 3 : 0, leads, hasLeads: leads.length > 0, noLeads: leads.length === 0,
        vis7: S.vis === 7, vis30: S.vis === 30, setVis7: () => set({ vis: 7 }), setVis30: () => set({ vis: 30 }),
        visN: sum(days), visL: sum(ld), hasVis: total > 0, noVis: total === 0,
        days: dayRows, daysCls: S.vis === 30 ? 'sy-days--30 sy-axis--30' : '',
        funnel: fn.map((v, i) => { const tip = i === 0 ? 'Все посетители за период' : v + ' из ' + fn[i - 1] + ', ' + Math.round(v / (fn[i - 1] || 1) * 100) + '%'; return { t: FT[i], v, tip, label: FT[i] + ': ' + (i === 0 ? v : tip), w: Math.max(2, Math.round(v / (fn[0] || 1) * 100)) + '%' }; }),
        ppPhone: S.ppv === 'phone', ppDesk: S.ppv === 'desk', ppSetPhone: () => set({ ppv: 'phone' }), ppSetDesk: () => set({ ppv: 'desk' }),
        cards: [
          card('', 'Название', site.name, site.slug + '.housebook.site', 1),
          card('', 'Логотип', site.logo ? 'Загружен' : 'Монограмма «' + k.mono(site.name) + '»', site.logo ? 'Показывается в шапке сайта' : 'Пока без логотипа', 2),
          card('', 'Цвет', colorName, site.color, 3, { dot: true }),
          card('', 'О Вас', site.sign || 'Подпись не указана', site.langs.join(', '), 4),
          card('', 'Объекты', sc, site.scope === 'all' ? '12 объектов в 5 странах' : 'Остальные клиенты не увидят', 5),
          card('', 'Валюта', site.cur, 'В ней показываются цены', 5),
          card('sy-set--w2', 'Кнопка связи', 'Чарли в Telegram', 'С Вашим кодом PRG7K2. Личные контакты на сайте не показываются.', 6)
        ]
      }, this.pvVals('p', site, S.ppv));
    }
    /* мастер */
    const slugS = this.slugState(d), tr = S.tried;
    const sel = d.projects;
    const countries = ['ОАЭ', 'Таиланд', 'Кипр', 'Грузия', 'Турция'];
    const wz = S.wiz, last = wz === 6;
    const TT = ['', 'Название и адрес', 'Логотип', 'Цвет', 'О Вас', 'Какие объекты показывать', S.edit ? 'Кнопка связи' : 'Всё готово'];
    const alts = [d.slug + '-1', d.slug + '-agent', d.slug + '-hb'].filter((a) => k.TAKEN.indexOf(a) < 0 && a.length <= 30);
    const setProj = (list) => this.setD({ projects: list });
    Object.assign(V, {
      wizOn: wz > 0, wizClose: () => set({ wiz: 0, edit: false }), step: wz, wizT: TT[wz],
      dots: [1, 2, 3, 4, 5, 6].map((n) => (n < wz ? 'is-done' : n === wz ? 'is-cur' : '')),
      s1: wz === 1, s2: wz === 2, s3: wz === 3, s4: wz === 4, s5: wz === 5, s6: wz === 6,
      wNext: (e) => this.wNext(e), wBack: () => set({ wiz: Math.max(1, wz - 1), tried: false }),
      showCancel: S.edit, showBack: !S.edit && wz > 1, showNext: !S.edit && !last, showPub: S.edit || last,
      pubT: S.edit ? 'Сохранить' : 'Опубликовать',
      notEdit: !S.edit,
      dName: d.name, nameCls: tr && !d.name.trim() ? 'is-err' : '', onName: (e) => { const v = e.target.value; this.setD(d.own || S.edit ? { name: v } : { name: v, slug: k.slugOf(v) }); },
      dSlug: d.slug, slugLocked: S.edit, onSlug: (e) => this.setD({ slug: e.target.value.toLowerCase().replace(/[^a-z0-9-]/g, '').slice(0, 30), own: true }),
      slugCls: !S.edit && (slugS === 'taken' || slugS === 'bad' || (tr && slugS === 'empty')) ? 'is-err' : '',
      slugErr: slugS === 'taken' ? 'Адрес занят, выберите другой' : slugS === 'bad' ? 'От 3 символов: латинские буквы, цифры и дефис' : 'Впишите адрес сайта',
      slugOk: !S.edit && slugS === 'ok', slugHint: !S.edit && slugS === 'empty', slugTaken: !S.edit && slugS === 'taken',
      alts: alts.map((a) => ({ t: a + '.housebook.site', go: () => this.setD({ slug: a, own: true }) })),
      dHasLogo: !!d.logo, dNoLogo: !d.logo, dLogo: d.logo, dColor: d.color, mono: k.mono(d.name),
      dropLogo: () => this.setD({ logo: '' }), onLogo: (e) => this.file(e, 'logo', 'logoErr'), logoErr: S.logoErr || '', logoCls: S.logoErr ? 'is-err' : '',
      colors: k.COLORS.map((c) => ({ hex: c[0], t: c[1], on: d.color === c[0], go: () => this.setD({ color: c[0] }) })),
      dHasPhoto: !!d.photo, dNoPhoto: !d.photo, dPhoto: d.photo, onPhoto: (e) => this.file(e, 'photo', 'photoErr'), photoErr: S.photoErr || '', photoCls: S.photoErr ? 'is-err' : '',
      dSign: d.sign, onSign: (e) => this.setD({ sign: e.target.value }),
      langs: ['Русский', 'English', 'Türkçe', 'العربية'].map((l) => ({ t: l, on: d.langs.indexOf(l) >= 0, go: () => this.setD({ langs: d.langs.indexOf(l) >= 0 ? d.langs.filter((x) => x !== l) : d.langs.concat([l]) }) })),
      scAll: d.scope === 'all', scPick: d.scope === 'pick', scAllCls: d.scope === 'all' ? 'is-on' : '', scPickCls: d.scope === 'pick' ? 'is-on' : '',
      setAll: () => this.setD({ scope: 'all' }), setPick: () => this.setD({ scope: 'pick', projects: sel.length ? sel : k.CAT.slice(0, 3).map((o) => o.id) }),
      countries: countries.map((c) => { const ids = k.CAT.filter((o) => o.co === c).map((o) => o.id); const on = ids.every((i) => sel.indexOf(i) >= 0); return { t: c + ' ' + ids.length, on, go: () => setProj(on ? sel.filter((i) => ids.indexOf(i) < 0) : sel.concat(ids.filter((i) => sel.indexOf(i) < 0))) }; }),
      pickCls: tr && d.scope === 'pick' && !sel.length ? 'is-err' : '',
      projects: k.CAT.map((o) => { const on = sel.indexOf(o.id) >= 0; return { t: o.n, s: o.c + ', ' + o.co, on, cls: on ? 'is-on' : '', go: () => setProj(on ? sel.filter((i) => i !== o.id) : sel.concat([o.id])) }; }),
      curs: ['USD', 'EUR', 'AED', 'RUB'].map((c) => ({ t: c, on: d.cur === c, go: () => this.setD({ cur: c }) })),
      dNameShow: d.name || 'Не указано', dCur: d.cur, logoWord: d.logo ? 'Загружен' : 'Монограмма «' + k.mono(d.name) + '»',
      colorName: (k.COLORS.filter((c) => c[0] === d.color)[0] || ['', ''])[1],
      scopeWord: d.scope === 'all' ? 'Весь каталог, 12 объектов' : 'Выбрано проектов: ' + sel.length,
      wpPhone: S.wpv === 'phone', wpDesk: S.wpv === 'desk', wpSetPhone: () => set({ wpv: 'phone' }), wpSetDesk: () => set({ wpv: 'desk' })
    }, this.pvVals('w', d, S.wpv));
    /* пример в пустом состоянии */
    Object.assign(V, this.pvVals('x', { name: 'Агент Housebook', slug: 'ilya', color: '#0E6A40', logo: '', photo: '', sign: 'Агент Housebook', langs: ['Русский', 'English'], scope: 'all', projects: [], cur: 'USD' }, 'phone'));
    return V;
  }
}

Component = (function (Base) { return class extends Base {
  constructor(props) { super(props); if (HB.isNovice()) this.state.site = null; }
  renderVals() { const v = super.renderVals(); const S = this.state, set = (o) => this.setState(o);  return v; }
}; })(Component);
